#[tauri::command] pub async fn hardware_info()->serde_json::Value {
 let mut result=serde_json::json!({"architecture":std::env::consts::ARCH,"os":std::env::consts::OS,"native":true});
 #[cfg(target_os="macos")]{let read=|args:&[&str]|std::process::Command::new("/usr/sbin/sysctl").args(args).output().ok().and_then(|o|String::from_utf8(o.stdout).ok()).unwrap_or_default().trim().to_owned();if let Ok(total)=read(&["-n","hw.memsize"]).parse::<u64>(){result["totalMemory"]=total.into();}let chip=read(&["-n","machdep.cpu.brand_string"]);result["gpu"]=format!("{} — mémoire unifiée Apple Silicon lorsque disponible",chip).into();if let Ok(o)=std::process::Command::new("/usr/bin/sw_vers").arg("-productVersion").output(){result["os"]=format!("macOS {}",String::from_utf8_lossy(&o.stdout).trim()).into();}if let Ok(o)=std::process::Command::new("/usr/bin/vm_stat").output(){let text=String::from_utf8_lossy(&o.stdout);let page=text.lines().next().and_then(|s|s.split("page size of ").nth(1)).and_then(|s|s.split_whitespace().next()).and_then(|s|s.parse::<u64>().ok()).unwrap_or(16384);let count:u64=text.lines().filter(|s|s.starts_with("Pages free:")||s.starts_with("Pages inactive:")).filter_map(|s|s.split(':').nth(1)?.trim().trim_end_matches('.').parse::<u64>().ok()).sum();result["availableMemory"]=(count*page).into();}}
 result
}
